from people_a import cat

cat("heroes", "Judges & Heroes", "Unlikely heroes from Israel’s wild early days.", "gideon", [
 dict(id="deborah", name="Deborah", role="Prophet and judge who led Israel to victory", art=None,
  facts=["Only female judge", "Held court under a palm tree", "Led an army"],
  cards=[
   ("Who she was", "Deborah was a prophet and the leader of Israel. People came to her under a palm tree to settle their disputes."),
   ("Going to war", "God told her that Barak should lead 10,000 men against Sisera, a general with 900 iron chariots. Barak said he’d only go if Deborah came. She went."),
   ("Victory", "God sent a storm and confusion; Israel won. Sisera fled on foot and was killed by a woman named Jael. Deborah and Barak sang a victory song."),
  ], read=[("Judges",4,"Deborah and Barak"),("Judges",5,"Deborah’s song")]),
 dict(id="gideon", name="Gideon", role="The scared farmer God called a mighty warrior", art="gideon",
  facts=["Hid from enemies", "Asked for signs with a fleece", "Won with 300 men"],
  cards=[
   ("Who he was", "Gideon was threshing wheat in hiding, scared of the Midianite raiders, when an angel showed up and said, “The Lord is with you, mighty warrior!”"),
   ("Prove it", "Gideon wasn’t sure. He put a wool fleece out at night and asked God to make it wet while the ground stayed dry — then the opposite the next night. God did both."),
   ("Only 300", "Gideon gathered 32,000 men. God said that was too many — Israel would brag. God cut it down to 300."),
   ("Jars and torches", "At night the 300 surrounded the enemy camp, smashed jars, held up torches, blew trumpets and shouted. The Midianites panicked and ran."),
  ], read=[("Judges",6,"Gideon’s call and the fleece"),("Judges",7,"The 300")]),
 dict(id="samson", name="Samson", role="The strongman with a weakness", art="samson-death",
  facts=["Never cut his hair", "Killed a lion barehanded", "Betrayed by Delilah"],
  cards=[
   ("Who he was", "Before Samson was born, God said he must never cut his hair as a sign he was set apart for God. God gave him incredible strength."),
   ("Super strength", "He tore apart a lion with his bare hands, beat a thousand Philistines with a donkey’s jawbone, and carried off a city’s gates."),
   ("Delilah", "Samson fell for Delilah, and the Philistines paid her to find his secret. She nagged until he told her. While he slept, she had his hair cut. His strength left, and they blinded him and chained him."),
   ("The last prayer", "At a huge Philistine party, blind Samson stood between two pillars and prayed, “God, give me strength one more time.” He pushed, and the whole building came down."),
  ], read=[("Judges",13,"Samson’s birth"),("Judges",16,"Samson and Delilah")]),
 dict(id="ruth", name="Ruth", role="The loyal foreigner who became great-grandma of a king", art="ruth-naomi",
  facts=["From Moab", "Loyal to Naomi", "Married Boaz"],
  cards=[
   ("Who she was", "Ruth was from Moab, a country that was often Israel’s enemy. She married an Israelite man, but he died, along with his brother and father."),
   ("“Where you go, I’ll go”", "Her mother-in-law Naomi decided to go back to Israel and told Ruth to go home. Ruth refused: “Where you go I will go. Your people will be my people, and your God my God.”"),
   ("Gleaning", "In Bethlehem, Ruth picked up leftover grain in the fields to feed them both. The field’s owner, Boaz, noticed her kindness and protected her."),
   ("A love story", "Boaz married Ruth. Their son Obed was the grandfather of King David — making Ruth an ancestor of Jesus."),
  ], read=[("Ruth",1,"Ruth stays with Naomi"),("Ruth",2,"Ruth meets Boaz"),("Ruth",4,"A wedding")]),
 dict(id="hannah", name="Hannah", role="The mother whose tearful prayer was answered", art=None,
  facts=["Couldn’t have children", "Prayed at the temple", "Mother of Samuel"],
  cards=[
   ("Who she was", "Hannah badly wanted a child, but couldn’t have one. Her husband’s other wife mocked her for years."),
   ("The prayer", "At the house of God, Hannah prayed so hard her lips moved without sound. The priest Eli thought she was drunk. She said, “I was pouring out my soul to the Lord.”"),
   ("Answered", "God gave her a son, Samuel. She kept her promise and brought him to serve at God’s house when he was young. Later God gave her five more children."),
  ], read=[("1 Samuel",1,"Hannah’s prayer"),("1 Samuel",2,"Hannah’s song")]),
 dict(id="samuel", name="Samuel", role="The boy who heard God’s voice and anointed kings", art=None,
  facts=["Hannah’s son", "“Speak, Lord”", "Anointed Saul and David"],
  cards=[
   ("Who he was", "Samuel grew up at God’s house, helping the old priest Eli."),
   ("A voice at night", "One night Samuel heard someone call his name. He ran to Eli three times. Eli realized it was God and told him to say, “Speak, Lord, your servant is listening.”"),
   ("Kingmaker", "Samuel became Israel’s prophet and leader. When the people demanded a king, he anointed Saul — and later, when Saul turned away from God, he anointed a shepherd boy named David."),
   ("Why it matters", "God told Samuel: “People look at the outside, but the Lord looks at the heart.”"),
  ], read=[("1 Samuel",3,"“Speak, Lord”"),("1 Samuel",16,"Samuel anoints David")]),
])

cat("kings", "Kings & Queens", "The rulers of Israel and Judah — the good, the bad and the in-between.", "solomon-judgment", [
 dict(id="saul", name="Saul", role="Israel’s first king", art=None,
  facts=["Tall and handsome", "Disobeyed God", "Jealous of David"],
  cards=[
   ("Who he was", "Saul was a head taller than everyone and looked like a king. Samuel anointed him as Israel’s first king."),
   ("Going his own way", "Saul started well, but kept doing things his way instead of God’s. Samuel told him, “To obey is better than sacrifice,” and that God had chosen someone else."),
   ("Jealousy", "When young David became a hero, Saul got so jealous he threw spears at him and hunted him for years."),
   ("How it ended", "In a losing battle against the Philistines, badly wounded, Saul fell on his own sword."),
  ], read=[("1 Samuel",9,"Saul is chosen"),("1 Samuel",15,"Obedience over sacrifice"),("1 Samuel",31,"Saul’s death")]),
 dict(id="david", name="David", role="Shepherd, giant-killer, king — “a man after God’s own heart”", art="goliath",
  facts=["Youngest of 8 brothers", "Killed Goliath", "Wrote many Psalms"],
  cards=[
   ("Who he was", "David was the youngest son, out watching sheep, when Samuel came to anoint the next king. Nobody thought to call him in."),
   ("The giant", "Goliath, a 9-foot Philistine warrior, mocked Israel for 40 days. Teenage David said, “I come against you in the name of the Lord,” and dropped him with one stone from his sling."),
   ("King", "After years running from Saul — and twice refusing to kill him — David became king and made Jerusalem the capital. He wrote many of the Psalms."),
   ("His big failure", "David slept with Bathsheba, another man’s wife, and had her husband killed to cover it up. When the prophet Nathan confronted him, David confessed and wrote Psalm 51: “Create in me a clean heart, O God.”"),
   ("Why it matters", "God promised one of David’s descendants would rule forever. That’s why Jesus is called the “Son of David.”"),
  ], read=[("1 Samuel",16,"David is anointed"),("1 Samuel",17,"David and Goliath"),("2 Samuel",12,"Nathan confronts David"),("Psalms",22,"“The Lord is my shepherd”")]),
 dict(id="solomon", name="Solomon", role="The wisest king — who lost his way", art="solomon-judgment",
  facts=["Son of David", "Built the Temple", "Wrote Proverbs"],
  cards=[
   ("Who he was", "Solomon was David and Bathsheba’s son. When God offered him anything he wanted, he asked for wisdom to lead well."),
   ("The baby case", "Two women claimed the same baby. Solomon said, “Cut the baby in half.” The real mother cried, “No! Give it to her!” — and Solomon knew who the real mother was."),
   ("Glory years", "He built God’s Temple in Jerusalem, wrote thousands of proverbs, and became so famous the Queen of Sheba came to test him."),
   ("How it ended", "Solomon married hundreds of foreign wives, and in his old age they turned his heart to other gods. After he died, the kingdom split in two."),
  ], read=[("1 Kings",3,"Asking for wisdom"),("1 Kings",8,"The Temple"),("1 Kings",11,"Solomon turns away")]),
 dict(id="esther", name="Esther", role="The queen who risked her life to save her people", art="esther",
  facts=["Jewish orphan", "Became queen of Persia", "“For such a time as this”"],
  cards=[
   ("Who she was", "Esther was a Jewish orphan raised by her cousin Mordecai in Persia. She was chosen to be queen — but kept her background secret."),
   ("The plot", "The king’s top official, Haman, hated Mordecai and got the king to sign an order to kill every Jew in the empire."),
   ("Such a time as this", "Mordecai begged Esther to go to the king. But going in without being called could mean death. Mordecai said, “Who knows — maybe you became queen for such a time as this.”"),
   ("If I die, I die", "Esther fasted three days, then walked in. The king held out his golden scepter. At a dinner she revealed Haman’s plot. Haman was executed, and the Jews were saved. Jews still celebrate it at Purim."),
  ], read=[("Esther",4,"“Such a time as this”"),("Esther",5,"Before the king"),("Esther",7,"Haman exposed")]),
 dict(id="hezekiah", name="Hezekiah", role="The king who prayed when an army surrounded him", art="sennacherib",
  facts=["King of Judah", "Tore down idols", "God added 15 years to his life"],
  cards=[
   ("Who he was", "Hezekiah was one of Judah’s best kings. He destroyed the idols his father had set up and led the people back to God."),
   ("Surrounded", "The Assyrian king Sennacherib surrounded Jerusalem and sent a letter mocking God. Hezekiah spread the letter out in the temple and prayed."),
   ("One night", "That night the angel of the Lord struck the Assyrian camp, and Sennacherib went home."),
   ("15 more years", "When Hezekiah got deathly sick, he cried and prayed. God said, “I heard your prayer and saw your tears,” and gave him 15 more years."),
  ], read=[("2 Kings",19,"Jerusalem saved"),("2 Kings",20,"15 more years")]),
 dict(id="josiah", name="Josiah", role="The boy king who rediscovered God’s Word", art=None,
  facts=["King at age 8", "Found the lost Book of the Law", "Led a revival"],
  cards=[
   ("Who he was", "Josiah became king of Judah when he was just 8 years old, after his father was assassinated."),
   ("A lost book", "While repairing the Temple, workers found the Book of the Law — it had been lost and forgotten. When it was read to Josiah, he tore his clothes in grief."),
   ("Turning back", "Josiah read it to all the people, destroyed the idols across the land, and held the greatest Passover in hundreds of years."),
  ], read=[("2 Kings",22,"The lost book"),("2 Kings",23,"Josiah’s reforms")]),
])

cat("prophets", "Prophets", "The people God sent to speak for Him.", "chariot", [
 dict(id="elijah", name="Elijah", role="The fiery prophet who never died", art="carmel",
  facts=["Faced 450 false prophets", "Fed by ravens", "Taken up in a whirlwind"],
  cards=[
   ("Who he was", "Elijah was a prophet during the reign of wicked King Ahab and Queen Jezebel, who led Israel to worship the false god Baal."),
   ("No rain", "Elijah told Ahab it wouldn’t rain until he said so. During the drought, ravens brought him food, and a poor widow’s flour and oil never ran out."),
   ("Showdown", "On Mount Carmel, Elijah challenged 450 prophets of Baal: whichever god sends fire is the real one. They shouted all day — nothing. Elijah soaked his altar with water and prayed once. Fire fell from heaven."),
   ("Burned out", "Then Jezebel threatened to kill him, and he ran into the desert and asked to die. An angel let him sleep and fed him. Later God spoke to him — not in wind, earthquake or fire, but in a gentle whisper."),
   ("How it ended", "Elijah never died. A chariot of fire appeared, and he was taken up to heaven in a whirlwind."),
  ], read=[("1 Kings",17,"Ravens and the widow"),("1 Kings",18,"Fire on Mount Carmel"),("1 Kings",19,"The gentle whisper"),("2 Kings",2,"Chariot of fire")]),
 dict(id="elisha", name="Elisha", role="Elijah’s apprentice, with a double portion", art=None,
  facts=["Left his plow to follow Elijah", "Asked for a “double portion”", "Many miracles"],
  cards=[
   ("Who he was", "Elisha was plowing a field when Elijah threw his cloak over him — a sign to follow. Elisha burned his plow and went."),
   ("Double portion", "Before Elijah was taken to heaven, Elisha asked for a double share of his spirit. He picked up Elijah’s cloak, struck the Jordan River, and it parted."),
   ("Miracles", "Elisha made a widow’s oil keep pouring, raised a boy from the dead, and healed Naaman, an enemy general, of leprosy by telling him to wash in the Jordan seven times."),
  ], read=[("2 Kings",2,"The double portion"),("2 Kings",4,"Oil and a boy raised"),("2 Kings",5,"Naaman healed")]),
 dict(id="isaiah", name="Isaiah", role="The prophet who saw Jesus coming 700 years early", art="isaiah",
  facts=["Saw God’s throne", "“Here I am, send me”", "Most quoted prophet in the New Testament"],
  cards=[
   ("Who he was", "Isaiah lived in Jerusalem about 700 years before Jesus and spoke to several kings of Judah."),
   ("Send me", "He had a vision of God on His throne with angels calling, “Holy, holy, holy.” He felt unworthy. An angel touched his lips with a burning coal. When God asked, “Who will go?”, Isaiah said, “Here I am. Send me!”"),
   ("Seeing ahead", "Isaiah wrote that a virgin would have a son called Immanuel, “God with us,” and described a servant who would be “pierced for our sins” and heal us by His wounds. Christians see Jesus all over Isaiah."),
  ], read=[("Isaiah",6,"“Send me”"),("Isaiah",9,"“For to us a child is born”"),("Isaiah",53,"The suffering servant")]),
 dict(id="jeremiah", name="Jeremiah", role="The weeping prophet", art="jeremiah",
  facts=["Called as a teen", "Warned Jerusalem for 40 years", "Thrown into a muddy well"],
  cards=[
   ("Who he was", "God called Jeremiah when he was young: “Before you were born, I knew you.” Jeremiah said, “I’m too young.” God said, “Don’t say that. I’ll be with you.”"),
   ("Nobody listened", "For about 40 years he warned Jerusalem that Babylon would destroy it if they didn’t turn back to God. He was mocked, beaten, and thrown into a muddy cistern."),
   ("Hope anyway", "Even as the city fell, Jeremiah shared God’s promise: “I know the plans I have for you — plans to give you a future and a hope.”"),
  ], read=[("Jeremiah",1,"Jeremiah’s call"),("Jeremiah",29,"“A future and a hope”"),("Jeremiah",38,"In the cistern")]),
 dict(id="daniel", name="Daniel", role="The teenager who stayed faithful in Babylon", art="lions-den",
  facts=["Taken captive as a teen", "Interpreted dreams", "Survived the lions’ den"],
  cards=[
   ("Who he was", "Daniel was a young man taken from Jerusalem to Babylon. He was trained for the king’s service but decided to stay faithful to God, even about what he ate."),
   ("Dreams and a hand", "God gave Daniel the ability to explain the king’s dreams. Later, at a wild party, a hand appeared and wrote on the wall. Daniel explained it: the kingdom is over. That night the king died."),
   ("The lions", "Jealous officials got a law passed that nobody could pray to anyone but the king. Daniel kept praying three times a day with his window open. He was thrown to the lions — and God shut their mouths."),
  ], read=[("Daniel",1,"Daniel in Babylon"),("Daniel",5,"Writing on the wall"),("Daniel",6,"The lions’ den")]),
 dict(id="shadrach", name="Shadrach, Meshach & Abednego", role="Three friends who wouldn’t bow", art="furnace",
  facts=["Daniel’s friends", "Refused to worship a statue", "A fourth man in the fire"],
  cards=[
   ("Who they were", "Three young Jewish men serving in Babylon with Daniel."),
   ("Bow or burn", "King Nebuchadnezzar built a 90-foot gold statue and ordered everyone to bow. The three refused. They told the king: “Our God can save us. But even if He doesn’t — we still won’t bow.”"),
   ("The fourth man", "The furnace was heated seven times hotter. They were thrown in — but the king saw four men walking in the fire, and the fourth looked like a son of the gods. They came out without even smelling like smoke."),
  ], read=[("Daniel",3,"The fiery furnace")]),
 dict(id="jonah", name="Jonah", role="The prophet who ran from God", art="jonah-whale",
  facts=["Ran the other way", "Swallowed by a great fish", "Upset when God forgave"],
  cards=[
   ("Who he was", "God told Jonah to go to Nineveh, the capital of Israel’s brutal enemy, and warn them. Jonah got on a ship going the opposite direction."),
   ("The fish", "A huge storm hit. Jonah told the sailors to throw him overboard, and the storm stopped. A great fish swallowed Jonah, and he was inside it three days and nights, praying. Then it spit him onto the beach."),
   ("Nineveh changes", "Jonah finally preached in Nineveh. The whole city — even the king — turned from evil. God had mercy and didn’t destroy them."),
   ("Jonah sulks", "Jonah was angry. He wanted them punished. God asked him: “Shouldn’t I care about this great city?”"),
  ], read=[("Jonah",1,"Running away"),("Jonah",2,"Inside the fish"),("Jonah",3,"Nineveh repents"),("Jonah",4,"Jonah’s anger")]),
 dict(id="job", name="Job", role="The good man who lost everything", art="job",
  facts=["Lost his family and wealth", "Asked God “why?”", "Restored double"],
  cards=[
   ("Who he was", "Job was a rich, good man who loved God. Satan claimed Job only loved God because life was easy."),
   ("Everything gone", "In one day Job lost his animals, his servants, and all ten of his children. Then he got painful sores all over his body. He said, “The Lord gave, and the Lord has taken away. Blessed be the name of the Lord.”"),
   ("Bad advice", "Three friends came and insisted Job must have done something to deserve it. Job knew he hadn’t, and he begged God for answers."),
   ("God answers", "God spoke out of a storm — not with explanations but with questions: “Where were you when I made the earth?” Job was humbled. God restored him with twice what he had before."),
  ], read=[("Job",1,"Job loses everything"),("Job",38,"God answers"),("Job",42,"Job restored")]),
])

cat("villains", "Villains & Rivals", "The people who opposed God — and how it turned out.", "darkness", [
 dict(id="pharaoh", name="Pharaoh of the Exodus", role="The king who wouldn’t let God’s people go", art="passover",
  facts=["King of Egypt", "Ten plagues", "Chased Israel into the sea"],
  cards=[
   ("Who he was", "The Bible doesn’t give his name. He ruled Egypt and kept the Israelites as slaves."),
   ("Hard heart", "Moses said, “Let my people go.” Pharaoh refused. God sent ten plagues — blood, frogs, gnats, flies, dead livestock, boils, hail, locusts and darkness. Each time Pharaoh promised, then changed his mind."),
   ("The last plague", "Finally the firstborn sons of Egypt died, including Pharaoh’s own. He let Israel go — then changed his mind again and chased them. His army drowned in the Red Sea."),
  ], read=[("Exodus",5,"“Who is the Lord?”"),("Exodus",12,"The last plague"),("Exodus",14,"The Red Sea")]),
 dict(id="goliath", name="Goliath", role="The giant who mocked God", art="goliath",
  facts=["Over 9 feet tall", "Philistine champion", "Beaten by a boy with a sling"],
  cards=[
   ("Who he was", "Goliath was a huge Philistine warrior from Gath, with armor weighing about 125 pounds."),
   ("The challenge", "For 40 days he came out every morning and dared Israel to send one man to fight him. Everyone was terrified."),
   ("One stone", "A shepherd boy named David took him on with a sling and five smooth stones. The first one sank into Goliath’s forehead."),
  ], read=[("1 Samuel",17,"David and Goliath")]),
 dict(id="jezebel", name="Jezebel", role="The queen who led Israel to worship Baal", art=None,
  facts=["Wife of King Ahab", "Killed God’s prophets", "Threatened Elijah"],
  cards=[
   ("Who she was", "Jezebel was a foreign princess who married Ahab, king of Israel. She brought Baal worship with her and pushed it on the whole nation."),
   ("Ruthless", "She hunted down God’s prophets and had an innocent man named Naboth killed so Ahab could take his vineyard."),
   ("How it ended", "Years later, a new king named Jehu rode into town. Jezebel’s own servants threw her from a window, just as Elijah had predicted."),
  ], read=[("1 Kings",21,"Naboth’s vineyard"),("2 Kings",9,"Jezebel’s end")]),
 dict(id="haman", name="Haman", role="The official who plotted to wipe out the Jews", art="esther",
  facts=["Top official in Persia", "Hated Mordecai", "Built his own gallows"],
  cards=[
   ("Who he was", "Haman was the most powerful official in the Persian Empire. Everyone had to bow to him — except Mordecai, a Jew."),
   ("The plot", "Furious, Haman decided to kill not just Mordecai but every Jew in the empire, and got the king to sign it. He built a tall gallows for Mordecai."),
   ("How it ended", "Queen Esther exposed the plot at a dinner. The king had Haman hanged on the very gallows he built for Mordecai."),
  ], read=[("Esther",3,"Haman’s plot"),("Esther",7,"Haman’s end")]),
 dict(id="herod", name="King Herod the Great", role="The king who tried to kill baby Jesus", art="nativity",
  facts=["King of Judea under Rome", "Rebuilt the Temple", "Paranoid and cruel"],
  cards=[
   ("Who he was", "Herod ruled Judea for Rome when Jesus was born. He was a huge builder — he expanded the Temple — but he was so paranoid he killed members of his own family."),
   ("The wise men", "When wise men from the East came asking where the newborn “King of the Jews” was, Herod pretended he wanted to worship Him too."),
   ("Bethlehem", "When the wise men didn’t come back, Herod ordered every boy two and under in Bethlehem killed. An angel had already warned Joseph, and the family escaped to Egypt."),
  ], read=[("Matthew",2,"Herod and the wise men")]),
 dict(id="pilate", name="Pontius Pilate", role="The governor who sent Jesus to the cross", art="ecce-homo",
  facts=["Roman governor of Judea", "Found no fault in Jesus", "Washed his hands"],
  cards=[
   ("Who he was", "Pilate was the Roman governor of Judea from about AD 26 to 36. Historians outside the Bible describe him as harsh."),
   ("The trial", "The religious leaders brought Jesus to him. Pilate questioned Jesus and said, “I find no basis for a charge against Him.” His wife even sent a message about a dream: have nothing to do with this innocent man."),
   ("Washing his hands", "The crowd shouted, “Crucify Him!” Afraid of a riot, Pilate washed his hands in front of them and said, “I am innocent of this man’s blood” — then handed Jesus over to be crucified."),
   ("Why it matters", "Christians still say his name every week in the Creed: Jesus “suffered under Pontius Pilate.” It ties the story to real history."),
  ], read=[("Matthew",27,"Pilate washes his hands"),("John",18,"“What is truth?”"),("John",19,"“Behold the man”")]),
])
